[IO.File]::WriteAllText((Join-Path $PWD 'resume.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Resumes dl/records.txt from the URL in `$1, but only onto the version it was started from:`n# dl/records.etag holds that version's ETag, saved by the first download.`nhave=`$(wc -c < dl/records.txt | tr -d ' ')`ncode=`$(curl -s -r `"`$have-`" -H `"If-Range: `$(cat dl/records.etag)`" -o dl/rest.part -w '%{http_code}' `"`$1`") || exit`ncase `"`$code`" in`n  206) cat dl/rest.part >> dl/records.txt; rm dl/rest.part; echo `"206: appended the missing bytes`" ;;`n  200) mv dl/rest.part dl/records.txt; echo `"200: the file changed; replaced it with the whole new version`" ;;`n  *) echo `"`$code: left dl/records.txt alone`"; exit 1 ;;`nesac`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh resume.sh http://127.0.0.1:8080/records.txt } finally { Stop-Process $server0 }
